SELECT AVG(`co`) `fieldData`,DATE_FORMAT( `data_time`, ${dateFormat} ) `timeFlag` FROM `environmental_monitoring`
where `data_time` between #{startTime} and #{endTime}
group by DATE_FORMAT( `data_time`, ${dateFormat} )

SELECT AVG(${dataField}) `fieldData`,DATE_FORMAT( `data_time`, ${dateFormat} ) `timeFlag` FROM `environmental_monitoring`
where `data_time` between #{startTime} and #{endTime}
group by DATE_FORMAT( `data_time`, ${dateFormat} )
